	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "player_comments_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"nickname" text NOT NULL,
	"author" text DEFAULT '游客' NOT NULL,
	"content" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "player_comments_nickname_check" CHECK (char_length(btrim("nickname")) BETWEEN 1 AND 80),
	CONSTRAINT "player_comments_author_check" CHECK (char_length(btrim("author")) BETWEEN 1 AND 24),
	CONSTRAINT "player_comments_content_check" CHECK (char_length(btrim("content")) BETWEEN 1 AND 300)
);
